INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114113, 'spa', 'visión profética', 'Revelación visual sobrenatural o profética, concentrada en Ezequiel y Daniel. En Ez 43:3 el profeta contempla una visión como la del río Quebar; Nm 8:4 describe el candelabro hecho ''conforme a la visión'' mostrada a Moisés. Este sentido distingue la visión reveladora de la percepción ordinaria y se vincula a la comunicación directa de Dios con sus profetas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114126, 'spa', 'vista, acto de ver', 'La facultad o el acto de la percepción visual, o un espectáculo contemplado. En Éx 3:3 Moisés dice ''iré y veré esta gran visión''; Dt 28:34 advierte sobre la locura ''por la vista de tus ojos''. Este sentido tiende un puente entre lo físico y lo figurado: lo que uno presencia, más que cómo algo se ve.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114158, 'spa', 'Visión profética', 'Experiencia visual sobrenatural mediante la cual Dios se comunica con profetas e individuos escogidos. A diferencia del emparentado mar''eh (apariencia), este sustantivo enfatiza el evento revelatorio en sí. En Números 12:6, Dios distingue la visión (mar''ah) como su medio elegido para la comunicación profética, mientras que el primer encuentro profético de Samuel en Siló se designa como mar''ah (1 Sam 3:15). Las experiencias de traslado de Ezequiel también se llaman ''visiones de Dios'' (Ez 1:1; 8:3; 40:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114167, 'spa', 'Maresa (ciudad de Judá)', 'El topónimo Maresa, que designa una ciudad judía en las tierras bajas de la Sefela y, en contextos genealógicos, un nombre de clan entre los descendientes de Caleb y Selá. Listada en la heredad de Judá (Jos 15:44), fortificada por Roboam (2 Cr 11:8) y escenario de la dramática victoria de Asá sobre la fuerza invasora cusita (2 Cr 14:9-10). Miqueas 1:15 la incluye en un juego de palabras profético sobre las ciudades de la Sefela.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114171, 'spa', 'Cabecera, lugar junto a la cabeza', 'El lugar junto a o al lado de la cabeza de alguien durante el sueño, señalando el punto de mayor proximidad y vulnerabilidad. Jacob coloca una piedra en su cabecera en Betel (Gn 28:11, 18), Mical pone un terafín en la cabecera de David (1 S 19:13, 16), Saúl duerme con su lanza en la cabecera en el campamento (1 S 26:7, 11-12, 16), y Elías encuentra provisiones puestas en su cabecera en el desierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114176, 'spa', 'Hija mayor de Saúl', 'Merab, la hija mayor del rey Saúl. En 1 Samuel 14:49 se la menciona junto a Mical en la familia de Saúl. En 18:17 Saúl la ofrece a David: «He aquí mi hija mayor Merab; te la daré por mujer». Pero el versículo 19 registra la traición: cuando Merab debía ser entregada a David, fue dada en cambio a Adriel. La grafía Μεροβ de la LXX confirma la identificación del nombre a través de las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114180, 'spa', 'Aumento o descendencia', 'Aumento o descendencia en sentido familiar, referido al crecimiento de un hogar o linaje. En 1 Samuel 2:33 aparece en estado constructo con una linea familiar, denotando el aumento o progenie que vendra de la casa de Eli. Los glosarios multilingues (''aumento de'') confirman un matiz concreto y generativo mas que una cantidad abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114182, 'spa', 'Establo de engorde', 'Establo o lugar donde se ataban y engordaban becerros para producir carne de primera calidad. En 1 Samuel 28:24 se refiere literalmente a un becerro criado en establo que podía prepararse rápidamente para un huésped de honor. Amós 6:4 lo usa para criticar a los poderosos que comen ''becerros del engorde'', simbolizando su lujo excesivo. Jeremías 46:21 lo emplea metafóricamente, comparando a los mercenarios de Egipto con ''becerros cebados''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114184, 'spa', 'Lugar a los pies', 'La zona junto a los pies de alguien, especialmente donde uno se acuesta a los pies de otro. Término predominante en Rut (Rut 3:4, 7, 8, 14), usado en las instrucciones de Noemí para el encuentro en la era con Booz, con matices espaciales y posiblemente eufemísticos. En Daniel 10:6 describe las extremidades inferiores de la visión angélica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114189, 'spa', 'Rebelarse, sublevarse o alzarse en desafío contra una autoridad soberana', 'Rebelarse, sublevarse o alzarse en desafío contra una autoridad soberana. Usado para la rebelión política — reyes vasallos que rompen obligaciones de tratado (Gn 14:4; 2 R 18:7, 20; 24:1) — y para la rebelión espiritual contra Dios (Nm 14:9; Jos 22:16-19; Neh 2:19). El español ''se rebeló/nos rebelamos'' y el cognado árabe marada (''ser audaz y atrevido en la rebelión'') confirman la fuerza de un desafío abierto y deliberado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114195, 'spa', 'Un participio sustantivado — ''rebelde, el que se rebela'' — que designa a persona', 'Un participio sustantivado — ''rebelde, el que se rebela'' — que designa a personas caracterizadas por la rebeldía. En Job 24:13 los ''rebeldes contra la luz'' son quienes rechazan la iluminación moral. Ezequiel 2:3 califica a Israel de nación ''rebelde'', y Ezequiel 20:38 habla de purgar a ''los rebeldes'' de entre el pueblo. El español traduce ''los rebeldes'', confirmando el paso de la acción verbal a una categoría fija de personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114213, 'spa', 'El nombre propio Mardoqueo, referido principalmente al líder judío en la corte p', 'El nombre propio Mardoqueo, referido principalmente al líder judío en la corte persa que cría a Ester y frustra el complot genocida de Amán (Est 2:5-7; 4:1-17; 8:1-2; 10:3), y secundariamente a una figura mencionada entre los que regresaron con Zorobabel (Esd 2:2; Neh 7:7). Posiblemente derivado del nombre divino babilónico Marduk. Todas las lenguas transliteran en vez de traducir este nombre propio fijo de la tradición bíblica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114219, 'spa', 'Caracterizacion persistente de Israel como rebelde', 'Caracterizacion persistente de Israel como rebelde: tres apariciones en Dt 9:7, 9:24 y 31:27 donde el participio o adjetivo מַמְרִים funciona como etiqueta resumen de la disposicion cronica de Israel hacia Dios. No narran un acto aislado de rebelion, sino que describen un rasgo nacional perdurable. El discurso final de Moises emplea este termino como veredicto acumulativo sobre toda la historia del desierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114220, 'spa', 'El sentido causativo Hifil', 'El sentido causativo Hifil: rebelarse contra, provocar a ira, desafiar activamente a una autoridad superior. Este es el grupo mas frecuente (18 apariciones), concentrado en Deuteronomio y los libros historicos donde se catalogan las rebeliones de Israel. En Dt 1:26 y 1:43, Israel se niega a subir y luego ataca presuntuosamente, ambos actos de rebelion contra el mandato explicito de Yahveh.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114221, 'spa', 'El sentido basico del Qal finito', 'El sentido basico del Qal finito: rebelarse, ser desobediente, actuar en desafio a la autoridad. Con 15 apariciones en todas las conjugaciones del Qal, este es el sentido de rebelion sin matiz causativo intensificador. En Nm 20:24 y 27:14, Moises y Aaron ''se rebelaron contra'' el mandamiento de Dios en Meriba; en 1 R 13:21 y 13:26, el varon de Dios ''desobedecio'' la palabra del SENOR.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114222, 'spa', 'El sentido participial/adjetival del Qal', 'El sentido participial/adjetival del Qal: rebelde, desafiante, usado sustantivamente para caracterizar a personas o comunidades como inherentemente rebeldes. Cinco apariciones, incluyendo la memorable formula legal בֵּן סוֹרֵר וּמוֹרֶה (''hijo contumaz y rebelde'', Dt 21:18, 20) y la exasperada interpelacion a Israel como הַמֹּרִים (''rebeldes!'') en Nm 20:10.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114225, 'spa', 'Un sentido estativo/adjetival', 'Un sentido estativo/adjetival: amargo, amargura, provocacion amarga. Cuatro apariciones donde la raiz se superpone o toma coloracion de la raiz relacionada מָרַר (''ser amargo''). En 1 Sam 30:6, David esta ''amargo de alma''; en 2 R 14:26, la afliccion de Israel es ''muy amarga''; en Lm 1:20, el infinitivo absoluto מָרוֹ intensifica el dolor de Jerusalen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114251, 'spa', 'Manantial amargo del Sinai', 'Nombre propio que designa el manantial amargo en el desierto del Sinai donde Israel se detuvo tras cruzar el mar. Las cinco apariciones se concentran en la narrativa del desierto de Exodo y Numeros (Ex 15:23 tres veces con he direccional; Nm 33:8-9 en el itinerario). El toponimo preserva la raiz ''amargo,'' vinculando el lugar con la prueba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114254, 'spa', 'Vagabundeo sin hogar', 'Condición de andar errante o carecer de hogar. Isaías 58:7 ordena: «¿No es compartir tu pan con el hambriento y traer a tu casa a los pobres sin hogar?» Lamentaciones 1:7 recuerda los tesoros de Jerusalén «en los días de su aflicción y vagabundeo». En 3:19, el hablante clama: «Recuerda mi aflicción y mi errar, el ajenjo y la hiel».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114257, 'spa', 'Las alturas celestiales, el ámbito donde Dios habita', 'Las alturas celestiales, el ámbito donde Dios habita: ''en lo alto'' o ''desde lo alto''. Es el uso poético dominante, presente en casi dos tercios de todas las ocurrencias. Dios envía auxilio ''desde lo alto'' (2 S 22:17); establece la paz ''en sus alturas'' (Job 25:2); el Espíritu se derrama ''desde lo alto'' (Is 32:15). Apunta siempre hacia arriba, al dominio trascendente de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114259, 'spa', 'Altura literal y física o terreno elevado', 'Altura literal y física o terreno elevado: la cumbre de una montaña, la cresta de un collado o tierras altas. Neftalí arriesgó su vida ''en las alturas del campo'' (Jue 5:18); Senaquerib se jactó de ascender ''la altura de los montes, los confines del Líbano'' (2 R 19:23). Mantiene el sentido geográfico concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114276, 'spa', 'Vocativo o título de interpelación que significa ''oh Excelso'', usado en dirigirs', 'Vocativo o título de interpelación que significa ''oh Excelso'', usado en dirigirse directamente a Dios o a una figura exaltada. La ocurrencia singular en el Salmo 56:2 emplea מָרוֹם como epíteto. No es geografía ni cosmología, sino doxología: la altura se ha convertido en un nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114277, 'spa', 'Uso sustantivado referido a personas exaltadas', 'Uso sustantivado referido a personas exaltadas: ''los encumbrados'' o ''los altos de la tierra''. Isaías 24:4 habla de los מְרוֹם del pueblo que languidecen bajo el juicio. La fuerza plural o colectiva distingue este sentido del vocativo singular: son seres humanos elevados en rango o soberbia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114287, 'spa', 'modo de correr', 'La manera o estilo fisico de correr, empleado para identificar a una persona por su forma de desplazarse. En 2 Samuel 18:27, el centinela reconoce al corredor como Ahimaaz hijo de Sadoc por su modo caracteristico de correr. Ambas apariciones en ese versiculo apuntan a este sentido concreto y atletico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114293, 'spa', 'Lugar amplio, espacio abierto', 'Lugar amplio, espacioso o abierto, usado literal y figurativamente. Literalmente describe un pastizal (Os 4:16) o las extensiones de la tierra (Hab 1:6). Figurativamente representa la liberación divina como ser llevado a un espacio abierto tras la angustia (2 Sam 22:20 = Sal 18:19; Sal 31:8; 118:5). El español ''lugar espacioso'' preserva la metáfora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114298, 'spa', 'Lugar distante, lejanía — un lugar distante o remoto, usado concretamente para t', 'Lugar distante, lejanía — un lugar distante o remoto, usado concretamente para tierras lejanas y abstractamente para la distancia espacial o relacional. Aparece con mayor frecuencia en la frase preposicional מִמֶּרְחָק (''desde lejos''), introduciendo ejércitos invasores convocados desde naciones distantes (Is 5:26; 10:3; 13:5; 30:27; 46:11; Jer 4:16; 5:15; 6:20) o expresando el conocimiento divino a través de vastas distancias (Sal 138:6). También se emplea positivamente para la esposa excelente que trae su pan desde lejos (Pr 31:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114304, 'spa', 'Pulir, bruñir (espada)', 'Pulir o bruñir una espada hasta lograr un acabado brillante y letal. El participio pasivo Pual mĕrûṭâ aparece repetidamente en Ezequiel 21, donde la espada de YHWH está «pulida» y lista para devorar. La referencia de 1 Reyes 7:45 extiende este sentido al bronce pulido de los utensilios del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114305, 'spa', 'Quedarse calvo (Nifal)', 'Nifal reflexivo: quedarse calvo o perder el cabello de forma natural, usado en las leyes diagnósticas sacerdotales de Levítico 13:40-41. Si el cabello se cae de la parte delantera o trasera de la cabeza de un hombre (yimmāreṭ), se le declara limpio, simplemente calvo, no enfermo. Es una pérdida involuntaria y natural, distinta del arranque violento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114307, 'spa', 'Arrancar pelo o barba', 'Arrancar o tirar activamente del cabello de la cabeza o la barba, expresando duelo intenso, indignación justa o humillación abusiva. Esdras se arranca el cabello por angustia (Esd 9:3), Nehemías arranca el cabello a los que violan el pacto (Neh 13:25), y el Siervo de Isaías ofrece sus mejillas a quienes le arrancan la barba (Is 50:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114309, 'spa', 'Pelado, desgastado', 'Participio pasivo Qal que describe la piel pelada o desgastada por el trabajo agotador. En Ezequiel 29:18, los soldados de Nabucodonosor trabajaron tan duramente en el asedio de Tiro que «todo hombro fue pelado», junto con «toda cabeza quedó calva». Este sentido enfatiza la abrasión por esfuerzo físico, no el pulido deliberado ni el arranque de cabello.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114313, 'spa', 'Sustantivo masculino que designa la rebelión deliberada contra Dios o la autorid', 'Sustantivo masculino que designa la rebelión deliberada contra Dios o la autoridad. Concentrado en la expresión בֵּית מְרִי (''casa de rebeldía'') de Ezequiel (Ez 2:5-8; 12:2-3; 17:12; 24:3). Samuel lo equipara con la adivinación (1 S 15:23), Moisés cita la מְרִי persistente de Israel (Dt 31:27), y Proverbios advierte que el rebelde ''solo busca el mal'' (Pr 17:11). El término evoca una obstinación tenaz y voluntaria contra la voluntad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114321, 'spa', 'Animal cebado, res engordada', 'Animal cebado o res engordada, criada con alimento rico para el sacrificio o el consumo festivo. Se usa para los animales sacrificiales cuya grasa (חֵלֶב) Dios rechaza cuando se ofrecen sin justicia (Is 1:11; Am 5:22), para las provisiones de banquetes reales en las narrativas de Adonías y David (1 R 1:9, 19, 25; 2 S 6:13), y en la imaginería escatológica del reino de paz (Is 11:6) y el gran festín de Ezequiel 39:18.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114327, 'spa', 'Nombre propio', 'Merib-Baal, nombre original del hijo de Jonatán, llamado después Mefiboset. 1 Crónicas 8:34 lo enumera dos veces en la genealogía: «El hijo de Jonatán fue Merib-Baal, y Merib-Baal engendró a Micaía». La variante reaparece en 9:40. Es la misma persona a quien David mostró bondad en 2 Samuel, que quedó lisiado a los cinco años cuando su nodriza lo dejó caer al huir tras la muerte de Saúl.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114328, 'spa', 'Meribá (topónimo)', 'El nombre propio Meribá, que designa el sitio en el desierto donde Israel probó a Dios disputando por agua. El Salmo 95:8 advierte ''No endurezcáis vuestro corazón como en Meribá'', y Ezequiel 47:19 y 48:28 usan ''las aguas de Meribá-Cades'' como referencia fronteriza. Las traducciones en diversos idiomas transliteran consistentemente el nombre en lugar de traducirlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114330, 'spa', 'Contienda, disputa', 'El sustantivo femenino común que significa contienda, disputa o riña entre personas. En Génesis 13:8, Abraham dice a Lot ''no haya merîvāh entre tú y yo'', y en Números 27:14 la forma constructa merîvat hā''ēdāh (''la contienda de la congregación'') describe la rebelión del pueblo en Cades. El español lo traduce como contienda o disputa, distinguiéndolo claramente del topónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114334, 'spa', 'Meribah (topónimo)', 'Topónimo Meribah (''contienda, querella''), asociado con la disputa de Israel contra YHWH por el agua en el desierto. Designa tanto Refidim (Éx 17:7, junto con Masah) como Cades (Nm 20:13, 24; Dt 33:8), donde Moisés golpeó la roca. La expresión mei meribah (''aguas de Meribah'') se volvió proverbial para referirse a la rebeldía (Sal 81:8; 95:8; 106:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114339, 'spa', 'Merayot (nombre sacerdotal)', 'El nombre propio Merayot (מְרָיוֹת), que designa a individuos sacerdotales en los registros genealógicos y templarios de Israel. Aparece en la línea sumo sacerdotal aarónica en 1 Crónicas 6:6-7, 52 y Esdras 7:3 como antepasado de Sadoc; en 1 Crónicas 9:11 y Nehemías 11:11 como parte del liderazgo sacerdotal postexílico; y en Nehemías 12:15 como cabeza de una casa sacerdotal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114341, 'spa', 'Miriam (nombre propio) -- Nombre propio femenino Miriam (מִרְיָם), que identific', 'Miriam (nombre propio) -- Nombre propio femenino Miriam (מִרְיָם), que identifica principalmente a la profetisa y hermana de Moises y Aaron. Aparece dirigiendo la alabanza tras el Exodo (Ex 15:20-21), cuestionando la autoridad de Moises (Nm 12:1-15), muriendo en Cades (Nm 20:1) y honrada en Miqueas 6:4 como una de los tres lideres fundacionales de Israel. La forma septuagintal Μαριαμ dio origen al nombre Maria en la tradicion posterior. Un hombre judahita tambien lleva este nombre (1 Cr 4:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114347, 'spa', 'Asiento de montura', 'Asiento para cabalgar, carro o silla de montar. 1 Reyes 4:26 registra que Salomón tenía «caballos para sus carros», las plataformas necesarias para su fuerza militar. Levítico 15:9 establece que «toda silla de montar sobre la que cabalgue el que tiene flujo será inmunda», pues el asiento se vuelve ritualmente impuro. Cantares 3:10 describe el palanquín de Salomón: «hizo su asiento de púrpura».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114348, 'spa', 'Carro, carro de guerra', 'Carro, carro de guerra. Vehículo tirado por caballos usado principalmente como carro de guerra, frecuentemente emparejado con סוּס (''caballo'') como endíadis militar. Abarca desde los carros de Faraón en el mar (Éx 14:25) hasta las importaciones comerciales de Salomón (1 R 10:29) y los cuatro carros apocalípticos de Zacarías (Zac 6:1). Se distingue del colectivo רֶכֶב (''carruaje colectivo'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114375, 'spa', 'Engaño, traición', 'Engaño, traición. Engaño, traición o fraude como falla moral, que abarca prácticas comerciales deshonestas (''balanzas engañosas,'' Am 8:5; Pr 11:1), habla astuta (Sal 52:6; 109:2) y traición interpersonal (Gn 27:35; 2 R 9:23). Las traducciones en distintas lenguas convergen en un solo concepto — ''engaño'' en español, ''tromperie'' en francés, ''Betrug'' en alemán — confirmando un perfil semántico unificado en las 39 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114384, 'spa', 'Meremot (nombre propio)', 'Nombre propio Meremot, que designa al menos dos o tres israelitas distintos del período postexílico. El más prominente es el sacerdote Meremot hijo de Urías, quien recibió los tesoros del templo de manos de Esdras (Esd 8:33) y reparó dos secciones de la muralla (Neh 3:4, 21). Las traducciones al español y al inglés transliteran el nombre de forma consistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114385, 'spa', 'Pisoteo, lo hollado', 'El acto de pisotear o la condición de ser hollado bajo los pies, empleado tanto en sentido literal como figurado para expresar destrucción y humillación absolutas. En Isaías 5:5 Dios entrega su viña al pisoteo; en Isaías 10:6 las naciones son hechas ''pisoteo como lodo en las calles''. Las traducciones existentes ''pisoteado'', ''para-pisoteo'' y ''para-ser-pisoteados'' reflejan la imagen visceral y física de ser aplastado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114395, 'spa', 'Amigo, compañero', 'Amigo íntimo, compañero o confidente, alguien unido por lealtad personal más que por mera proximidad. En Génesis 26:26 Ahuzat es el מֵרֵעַ de Abimelec, su consejero-amigo personal que lo acompaña para hacer un pacto con Isaac. En Jueces 14:11 los treinta compañeros de Sansón y el ''amigo del novio'' reflejan esta relación de cercanía y vínculo afectivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114402, 'spa', 'pasto, pastizal -- Lugar de apacentamiento o pastizal para el ganado, usado tant', 'pasto, pastizal -- Lugar de apacentamiento o pastizal para el ganado, usado tanto literal como figuradamente. Literal: la falta de pasto que impulso a la familia de Jacob a Egipto (Gn 47:4), los simeonitas hallando ricos pastizales (1 Cr 4:39-41), el territorio del asno montes (Job 39:8) y el ganado languideciendo sin pasto (Jl 1:18). Figurado: Dios como pastor proveyendo buen pasto a su rebano Israel (Ez 34:14, 18), las ruinas convertidas en pastizal como senal de juicio (Is 32:14) y los principes de Jerusalen como ciervos que no hallan pasto (Lm 1:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114409, 'spa', 'Pasto, dehesa (figurado)', 'Pasto o dehesa en sentido figurado, que designa al pueblo de Dios como el rebaño bajo su cuidado. Los sufijos pronominales («mi pasto», «tu pasto», «su pasto») siempre vinculan la imagen al Pastor divino. Salmos 74:1 y 79:13 usan «ovejas de tu pasto» en lamento, mientras que Salmos 95:7 y 100:3 lo emplean en adoración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114413, 'spa', 'Rebaño (metonimia)', 'Por metonimia, el rebaño mismo — los animales apacentados en lugar del sitio de pastoreo. En Jeremías 10:21, los pastores se han vuelto insensatos y «su rebaño fue dispersado», donde el desplazamiento del lugar a los seres vivos es una extensión semántica natural: el lugar de pastoreo pasa a representar lo que allí se apacienta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114416, 'spa', 'Sanidad, cura, remedio — el acto o resultado de sanar, aplicado tanto a la resta', 'Sanidad, cura, remedio — el acto o resultado de sanar, aplicado tanto a la restauración física como a la recuperación espiritual o nacional de Israel. Jeremías lamenta ''no hay sanidad para nosotros'' (Jer 14:19), mientras que Proverbios celebra la sanidad como fruto de la sabiduría: las palabras suaves son ''medicina para los huesos'' (Pr 16:24), y un mensajero fiel trae sanidad (Pr 13:17). Malaquías 3:20 vislumbra el sol de justicia con ''sanidad en sus alas.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114422, 'spa', 'Calma, compostura — una extensión figurada que significa calma, serenidad o mans', 'Calma, compostura — una extensión figurada que significa calma, serenidad o mansedumbre: la tranquilidad interior que sana la tensión relacional. Atestiguado solo en Eclesiastés 10:4, donde el sabio aconseja que la ''calma'' (מַרְפֵּא) puede apaciguar grandes ofensas de un gobernante. El salto semántico de la sanidad corporal a la compostura emocional revela cómo el pensamiento hebreo veía la serenidad como una forma de restauración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114425, 'spa', 'Grave o doloroso', 'Adjetivo que describe algo como grave, doloroso o severo, intensificando el sustantivo que modifica. En 1 Reyes 2:8 califica la maldición de Simei contra David como ''dolorosa''. Miqueas 2:10 habla de una ''destrucción grave'' que vendrá sobre Israel. Job 16:3 emplea una forma verbal que pregunta qué impulsa a alguien a seguir hablando. Job 6:25 es debatido: podría describir palabras ''rectas'' como fuertes o dolorosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114429, 'spa', 'Fregar o pulir', 'Fregar, pulir o limpiar a fondo. En sentido literal, describe el pulido de bronce (2 Crónicas 4:16, vasijas del templo de bronce ''bruñido'', paralelo a 1 Reyes 7:45). Levítico 6:28 ordena que la olla de bronce usada para la ofrenda por el pecado ''sea fregada'' y enjuagada. Jeremías 46:4 llama a los soldados a ''pulir las lanzas'' para la batalla. Proverbios 20:30 lo emplea figuradamente para la purificación interior mediante la disciplina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114430, 'spa', 'Caldo de carne', 'Caldo o jugo de carne obtenido por cocción. Jueces 6:19-20 describe la preparación de Gedeón: pone la carne en una canasta «y el caldo lo puso en una olla», luego «derrama el caldo» por orden del ángel. Isaías 65:4 condena a los idólatras: «que comen carne de cerdo, y caldo de cosas inmundas hay en sus vasijas» (lectura Qeré).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114433, 'spa', 'Mezcla de ungüento', 'Composición de ungüento o el acto de mezclar aceites perfumados. Éxodo 30:25 ordena preparar el aceite santo de la unción «compuesto según el arte del perfumista», una mezcla experta de especias y aceite. 1 Crónicas 9:30 señala que «algunos de los hijos de los sacerdotes preparaban la mezcla del ungüento». 2 Crónicas 16:14 describe la sepultura de Asá «en un lecho lleno de especias y perfumes compuestos».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114434, 'spa', 'amargar a alguien, tratar amargamente -- Piel transitivo', 'amargar a alguien, tratar amargamente -- Piel transitivo: amargar a alguien o atacar con encono. Genesis 49:23 describe a los arqueros que ''amargamente atacaron'' a Jose, y Exodo 1:14 relata como los egipcios ''amargaron'' la vida de Israel con dura servidumbre. El Piel intensifica la accion hostil del verbo base.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114435, 'spa', 'causar amargura (causativo) -- Hifil causativo finito', 'causar amargura (causativo) -- Hifil causativo finito: causar amargura, hacer amarga una situacion. Noemi se renombra Mara porque ''el Todopoderoso me ha llenado de amargura'' (Rt 1:20), y Job 27:2 atribuye su amargura a Dios. El Hifil subraya la agencia causal sobre el sufrimiento ajeno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114436, 'spa', 'rebelarse, actuar desafiantemente -- Sentido Hifil especializado de rebelion o d', 'rebelarse, actuar desafiantemente -- Sentido Hifil especializado de rebelion o desafio, atestiguado en Exodo 23:21 donde Dios advierte a Israel que no se ''rebele'' contra su angel. El puente semantico pasa por la provocacion: la rebelion amarga la relacion con Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114437, 'spa', 'ser amargo (estativo) -- Qal estativo', 'ser amargo (estativo) -- Qal estativo: ser o volverse amargo en sabor o en experiencia emocional. Isaias 24:9 conserva el sentido gustativo literal, mientras que Rut 1:13 y 2 Reyes 4:27 lo extienden a la angustia existencial. El hebreo emplea la misma raiz para el sabor y el sufrimiento, como ocurre tambien con el espanol ''amargo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114440, 'spa', 'enfurecerse, amargarse (reflexivo) -- Hitpael reflexivo', 'enfurecerse, amargarse (reflexivo) -- Hitpael reflexivo: enfurecerse o amargarse interiormente, expresando furia interna. Las dos ocurrencias aparecen en Daniel: el macho cabrio se ''enfurece'' (8:7) y el rey del sur ''se llena de furor'' (11:11). El Hitpael capta la cualidad reflexiva y autoconsunte de esta rabia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114442, 'spa', 'llorar amargamente (intensivo) -- Piel intensivo intransitivo', 'llorar amargamente (intensivo) -- Piel intensivo intransitivo: llorar con intensa amargura. En Isaias 22:4, el profeta clama ''dejadme llorar amargamente'' por la destruccion de Jerusalen. Se distingue del duelo adverbial Hifil de Zacarias por su intensidad autodirigida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114446, 'spa', 'lamentacion amarga (adverbial) -- Infinitivo absoluto Hifil usado adverbialmente', 'lamentacion amarga (adverbial) -- Infinitivo absoluto Hifil usado adverbialmente para modificar el duelo: amargamente, como en lamentacion amarga. Zacarias 12:10 lo emplea dos veces: ''lloraran amargamente'' y ''como el amargo dolor por un primogenito''. La funcion adverbial intensifica la expresion del luto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114448, 'spa', 'Hierbas amargas pascuales', 'Hierbas amargas requeridas para la Pascua. Éxodo 12:8 ordena comer la carne del cordero «con panes sin levadura y hierbas amargas». Números 9:11 repite la misma prescripción para la segunda Pascua. Lamentaciones 3:15 lo emplea en sentido figurado: «Me llenó de amarguras, me sació de hierbas amargas», describiendo la aflicción como ingestión forzada de lo amargo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114450, 'spa', 'Amargura o hiel', 'Cosas amargas, hiel o veneno en varios sentidos. Job 20:25 lo usa anatómicamente para la ''hiel'' o vesícula biliar (paralelo a ''espalda'' en el cuerpo). Job 20:14 lo emplea para el veneno: el alimento del impío se convierte en ''veneno de serpientes'' en su estómago. Job 13:26 lo usa figuradamente para las ''cosas amargas'' de Dios: juicios severos escritos contra el que sufre. Deuteronomio 32:32 habla de uvas de amargura y racimos ponzoñosos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114451, 'spa', 'Merari (nombre propio)', 'Merari (nombre propio). Nombre personal de Merari, tercer hijo de Leví y antepasado epónimo del clan merarita de los levitas. Todas las ocurrencias aparecen en contextos genealógicos o de servicio cultual: los censos del Pentateuco (Nm 3-4, 26), la asignación de ciudades levíticas (Jos 21) y las listas del servicio del templo del Cronista (1 Cr 6, 15, 23-24). Las traducciones lo transliteran uniformemente como ''Merari''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114460, 'spa', 'Carga física o peso', 'Carga física o peso. El sentido dominante: un peso o carga tangible llevada por animales (asnos en Éx 23:5, mulas en 2 R 5:17, camellos en 2 R 8:9) o cargada por personas en contextos como el transporte levítico del tabernáculo (Nm 4:15, 24, 27). Se extiende figurativamente a la ''carga'' de cuidar a personas (Nm 11:11; Dt 1:12), ser un peso para alguien (2 S 15:33; Job 7:20) y la carga aplastante de la iniquidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114463, 'spa', 'Acto de cargar o transportar', 'Acto de cargar o transportar. Sentido de nombre verbal que enfatiza la acción de cargar o transportar en lugar del objeto cargado. Aparece en contextos litúrgicos especializados: 1 Crónicas 15:22, 27 describe el ''transporte'' (o posiblemente la ''elevación'' del canto) durante la procesión del Arca, y 2 Crónicas 20:25 describe el acarreo del botín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114464, 'spa', 'Oráculo o pronunciamiento profético', 'Oráculo o pronunciamiento profético. Un ''oráculo'' o pronunciamiento solemne profético, que aparece en Proverbios 30:1 y 31:1 para introducir las palabras de Agur y de la madre del rey Lemuel. El vínculo semántico con ''carga'' puede ser que la palabra profética es ''puesta sobre'' o ''levantada por'' el que habla — un mensaje pesado de Dios que presiona sobre el profeta. Este sentido es mucho más común en el grupo afín מַשָּׂא de Isaías y los profetas menores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114473, 'spa', 'Tributo u obligación impuesta', 'Tributo u obligación impuesta. Un impuesto obligatorio o tributo — la ''carga'' impuesta a pueblos sometidos. En 2 Crónicas 17:11, los filisteos y árabes traen tributo a Josafat. La metáfora es transparente: los impuestos son una carga puesta sobre los hombros del obligado. Las traducciones en distintas lenguas lo expresan con su palabra habitual para carga.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114479, 'spa', 'Anhelo o elevación del deseo', 'Anhelo o elevación del deseo. Un sentido poco frecuente que denota el anhelo o la ''elevación'' del deseo del alma. En Ezequiel 24:25, Dios describe el templo como ''la elevación de su alma'' — el objeto hacia el cual todo su ser se inclina. Este sentido tiende un puente entre el levantamiento físico y la aspiración emocional, una extensión conmovedora presente solo en este pasaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114481, 'spa', 'Pronunciamiento profético solemne u oráculo que funciona típicamente como encabe', 'Pronunciamiento profético solemne u oráculo que funciona típicamente como encabezamiento introductorio de un discurso de juicio contra una nación extranjera. Domina la colección de oráculos de Isaías contra las naciones (Is 13:1; 15:1; 17:1; 19:1; 21:1, 11, 13; 22:1; 23:1). También introduce Nahúm (Nah 1:1), Habacuc (Hab 1:1) y la fórmula profética tardía ''oráculo de la palabra de YHWH'' (Zac 9:1; 12:1; Mal 1:1). Jeremías 23:33-40 contiene un célebre juego de palabras entre ''oráculo'' y ''carga''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114486, 'spa', 'Préstamo con interés', 'Préstamo a interés o la carga de deuda resultante. Nehemías 5:7 relata la reprensión: «Estáis cobrando interés a vuestros hermanos», usando este término para la práctica opresiva de préstamo. El versículo 10 continúa: «Abandonemos esta exacción de intereses». En 10:31 el pueblo se compromete a «perdonar toda deuda», renunciando a las prácticas usurarias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114494, 'spa', 'Artesas para amasar', 'Artesas o bateas usadas para preparar masa de pan. Éxodo 8:3 describe la plaga de ranas invadiendo los hogares egipcios, entrando incluso en ''tus artesas'' junto con los dormitorios y hornos, enfatizando la extensión total de la plaga. Éxodo 12:34 retrata a los israelitas en su salida apresurada llevando ''sus artesas envueltas en sus mantos'', con la masa sin leudar aún dentro. Deuteronomio 28:5,17 las incluye en las fórmulas de bendición y maldición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114495, 'spa', 'Tributo, impuesto, contribución — un tributo, impuesto o gravamen obligatorio, c', 'Tributo, impuesto, contribución — un tributo, impuesto o gravamen obligatorio, con tres apariciones (2 Cr 24:6, 9; Am 5:11), todas en contextos de recaudación institucionalizada. Joás reinstituye ''el tributo de Moisés'' para el tabernáculo (2 Cr 24:6); Amós condena a quienes exigen ''tributos de grano'' de los pobres.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114496, 'spa', 'Porción, regalo, presente — una porción, regalo u obsequio, el sentido más frecu', 'Porción, regalo, presente — una porción, regalo u obsequio, el sentido más frecuente con siete apariciones. José envía porciones (מַשְׂאוֹת) de su propia mesa a sus hermanos, recibiendo Benjamín cinco veces más (Gn 43:34). Ester distribuye regalos en su banquete de coronación (Est 2:18). La imagen subyacente es la de alimentos o bienes ''levantados'' y llevados a un destinatario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114497, 'spa', 'Señal, columna de fuego — una señal, específicamente una columna ascendente de h', 'Señal, columna de fuego — una señal, específicamente una columna ascendente de humo o fuego, con tres apariciones concentradas en la narrativa de Gabaa (Jue 20:38, 40) y Jeremías 6:1. La señal convenida para la emboscada israelita en Gabaa es una מַשְׂאֵת de humo que se eleva desde la ciudad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114502, 'spa', 'Carga, oráculo profético — una carga u oráculo profético, con dos apariciones (L', 'Carga, oráculo profético — una carga u oráculo profético, con dos apariciones (Lm 2:14; Sof 3:18). En Lamentaciones, los falsos profetas han visto ''oráculos vanos'' (מַשְׂאוֹת) para Jerusalén, usando la misma palabra que en otros lugares significa ''carga.'' Sofonías 3:18 habla de quienes llevan ''la carga del oprobio.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114504, 'spa', 'Alzamiento, elevar las manos — el alzar de las manos en oración, una única apari', 'Alzamiento, elevar las manos — el alzar de las manos en oración, una única aparición en el Salmo 141:2, donde el salmista pide que ''el alzar de mis manos'' sea como el sacrificio vespertino. Este es el sentido etimológicamente más primitivo del sustantivo: el simple acto de elevar, aquí ritualizado como un gesto de adoración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114510, 'spa', 'Engastes, monturas de filigrana', 'Engastes de filigrana de oro o monturas trenzadas usadas para asegurar piedras preciosas en las vestiduras sacerdotales. Las ocho ocurrencias en Éxodo (28:11, 13, 14, 25; 39:6, 13, 16, 18) describen el trabajo de orfebrería del efod y el pectoral, asociados siempre con ''oro'' (zahav). La única aparición en el Salmo 45:14 extiende la imagen al atuendo nupcial real, vinculando la magnificencia sacerdotal con la realeza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114513, 'spa', 'Abertura del vientre', 'La boca o abertura del vientre en el momento del parto. 2 Reyes 19:3 e Isaías 37:3 comparten la frase idéntica: «Los hijos han llegado a la abertura del parto, pero no hay fuerza para dar a luz», expresando total impotencia ante una crisis nacional. Oseas 13:13 advierte: «Es un hijo insensato, porque no se presenta a tiempo en la abertura del vientre», describiendo la insensatez de Efraín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114514, 'spa', 'rompientes u olas', 'Olas que revientan o rompientes del mar, usados literal y figuradamente para expresar angustia abrumadora. El Salmo 93:4 exalta la majestad de Dios sobre el oceano. Figuradamente, 2 Samuel 22:5 los empareja con la muerte, y Salmos 42:7, 88:7 y Jonas 2:3 emplean ''tus rompientes'' para retratar calamidades como acciones divinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114516, 'spa', 'Refugio alto, fortaleza', 'Refugio alto, fortaleza: baluarte elevado o refugio en las alturas, usado literalmente para una fortaleza física (Is 25:12; 33:16) pero predominantemente como metáfora del amparo protector de Dios. Los Salmos lo emplean como título divino en poesía de confianza: ''El SEÑOR es refugio alto para el oprimido'' (Sal 9:9), y aparece junto a ''roca,'' ''fortaleza'' y ''escudo'' en la acción de gracias de David (2 Sam 22:3; Sal 18:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114526, 'spa', 'Sacar del peligro', 'Sacar o extraer del peligro, particularmente del agua. Éxodo 2:10 explica el nombre de Moisés: «Porque de las aguas lo saqué», la hija del faraón rescatando al niño de la cesta en el Nilo. 2 Samuel 22:17 y Salmo 18:16 (textos paralelos) declaran: «Envió desde lo alto y me sacó; me extrajo de las muchas aguas», Dios librando de una amenaza abrumadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114527, 'spa', 'Moisés (nombre propio)', 'El nombre propio מֹשֶׁה (Moisés), referido exclusivamente al hijo de Amram y Jocabed, de la tribu de Leví, quien sacó a Israel de Egipto y medió el pacto en el Sinaí. Las 766 apariciones designan a este único individuo. Las variantes preposicionales (a Moisés, de Moisés, por medio de Moisés) reflejan encuadre sintáctico, no distinción semántica alguna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114537, 'spa', 'Desolación y ruina', 'Desolación o devastación, ruina completa. Sofonías 1:15 describe el Día del Señor: «Día de ira, día de angustia y aflicción, día de ruina y devastación», emparejando este término con múltiples sinónimos de destrucción. Job 30:3 retrata a los miserables que «roen la tierra reseca en la oscuridad de la desolación y el páramo». Job 38:27 habla de la lluvia de Dios «para saciar la tierra desolada y yerma».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114540, 'spa', 'apostata (epiteto personal) -- Usado como epiteto cuasi-adjetival que caracteriz', 'apostata (epiteto personal) -- Usado como epiteto cuasi-adjetival que caracteriza a una persona o comunidad como ''apostata, infiel, desleal'', funcionando en aposicion a un nombre propio. Concentrado en Jeremias 3:6-12, donde el profeta contrasta meshuvah Yisrael (''Israel la apostata'', el Reino del Norte) con bogedah Yehudah (''Juda la traidora''). La fuerza retorica depende de que la palabra se perciba como una caracterizacion definitoria, casi un sobrenombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114541, 'spa', 'apostasia, deslealtad -- Apostasia, deslealtad, descarrio', 'apostasia, deslealtad -- Apostasia, deslealtad, descarrio: sustantivo abstracto que designa el acto o la condicion de apartarse de Dios, aplicado a la infidelidad persistente de Israel y Juda. Jeremias acumula el plural meshuvoteikhem (''vuestras apostasias'', Jer 2:19; 3:22; 5:6) para enfatizar el caracter reiterado y acumulativo de la defeccion nacional. Oseas 14:5 promete que Dios ''sanara su apostasia'' y los amara de pura gracia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114556, 'spa', 'Medida o capacidad', 'Medida, capacidad o porción medida. Levítico 19:35 prohíbe la deshonestidad ''en juicio, en medida, en peso o en capacidad (מְשׂוּרָה)'', enumerando distintas dimensiones de la medición comercial. 1 Crónicas 23:29 asigna a los levitas la responsabilidad sobre ''toda medida y capacidad'' en el servicio del templo. Ezequiel 4:11 y 16 describen porciones estrictamente racionadas de agua y pan, simbolizando el asedio y juicio venidero sobre Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114557, 'spa', 'Gozo, exultación, deleite', 'Gozo, exultación, deleite: alegría intensa, exultación o deleite, a menudo anclado a fuentes concretas como la música, las ciudades o la celebración comunitaria. Isaías lo emplea para el gozo de los instrumentos acallados por el juicio (''el gozo de los panderos... el gozo de la lira,'' Is 24:8) y para las ruinas de los lugares festivos (Is 32:13-14), revirtiendo luego la imagen en promesas de restauración donde Jerusalén se convierte en ''gozo de muchas generaciones'' (Is 60:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114565, 'spa', 'Ungir ceremonialmente para consagración', 'Ungir ceremonialmente para consagración. Unción ritual para consagrar a una persona u objeto sagrado para el servicio divino. Este sentido dominante abarca reyes (1 Sam 9:16; 16:3), sacerdotes (Éx 28:41; 29:7), profetas (1 Re 19:16) y objetos cultuales como el tabernáculo, el altar y los utensilios (Éx 30:26; 40:9-11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114568, 'spa', 'Ser ungido o consagrado', 'Ser ungido o consagrado. Condición pasiva o estativa de haber recibido la unción sagrada, expresada mediante formas Nifal o participios pasivos del Qal. Describe tortas sin levadura untadas con aceite para las ofrendas (Éx 29:2; Lv 2:4; 7:12) y sacerdotes consagrados que han pasado por el rito (Nm 3:3; Lv 6:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114581, 'spa', 'Untar pintura o aceite cosmético', 'Untar pintura o aceite cosmético. Aplicación no sacral de una sustancia sobre una superficie o cuerpo con fines prácticos o cosméticos. Joacim pinta las paredes de su palacio con bermellón (Jer 22:14), un escudo es engrasado como preparación para la batalla (Is 21:5), y la élite complaciente se unge con aceites finos (Amós 6:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114603, 'spa', 'El aceite santo de unción propiamente dicho', 'El aceite santo de unción propiamente dicho: la mezcla especial de especias y aceite de oliva prescrita para consagrar el tabernáculo, sus utensilios, el altar y el sacerdocio aarónico. Aparece en la fórmula shemen hammishchah (''aceite de la unción'') a lo largo de Éxodo, Levítico y Números (Éx 25:6; 29:7, 21; 30:25, 31; 31:11; 35:8; 37:29; Lv 8:2, 10, 12; 21:10; Nm 4:16). Su fabricación estaba restringida exclusivamente al uso sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114610, 'spa', 'Destrucción, ruina', 'Destrucción o ruina abstracta — la devastación traída por el juicio divino, el hambre, la guerra o la peste. Éxodo 12:13 la usa con la preposición le- para señalar la plaga destructora que pasa sobre Israel; Ezequiel 5:16 y 25:15 la aplican a flechas y actos de venganza enviados «para destrucción». El campo semántico converge uniformemente en el sentido de devastación total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114612, 'spa', 'El Destructor (personificado)', 'Un Destructor personificado o semipersonificado — usado con el artículo o en estado constructo para nombrar a un agente específico de la ira divina. Jeremías 51:25 se dirige a Babilonia como har ha-mashchit («oh monte destruidor»), mientras que en 2 Reyes 23:13 la frase nombra un hito geográfico, el «monte de la corrupción» al sur del Monte de los Olivos donde había altares ilícitos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114629, 'spa', 'Nombre propio personal', 'Mesezabel, nombre propio que significa ''Dios libera'', llevado por hombres en la época de Nehemías. En Nehemías 3:4 aparece como abuelo de Mesulam, uno de los reconstructores del muro. En 10:21, un Mesezabel figura entre quienes sellaron el pacto. Nehemías 11:24 menciona a Petaías hijo de Mesezabel como funcionario ''al servicio del rey en todos los asuntos del pueblo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114630, 'spa', 'Ungido, rey o sacerdote', 'Ungido, rey o sacerdote. El uso central: una persona específica — rey o sumo sacerdote — consagrada mediante el rito de la unción con aceite sagrado. Se aplica a los reyes israelitas como ''el ungido de YHWH'' (meshiach YHWH) a lo largo de Samuel y los Salmos (1 S 24:6; Sal 2:2; 2 S 22:51), y al sumo sacerdote como ''el sacerdote ungido'' (Lv 4:3, 5, 16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114636, 'spa', 'El Mesías, título escatológico', 'El Mesías, título escatológico. El sentido titular y escatológico hallado en Daniel 9:25-26, donde ''un ungido'' (mashiach nagid) designa a un futuro libertador. En español se traduce distintivamente como ''Mesías,'' marcando el paso de sustantivo común a título propio. Este es el puente semántico hacia el griego neotestamentario Χριστός, y ambos pasajes de Daniel se distinguen de las demás ocurrencias por usar el término sin sufijo posesivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114638, 'spa', 'Unción, acto de consagración', 'Unción, acto de consagración. Un sentido participial en 2 Samuel 1:21 donde la referencia es al acto mismo de ungir — el escudo de Saúl ''no ungido con aceite.'' Aquí la palabra conserva su fuerza verbal en lugar de funcionar como título sustantivo. ''Ungir'' en español capta la dimensión procesual y verbal que distingue esta ocurrencia de los usos nominales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114640, 'spa', 'Ungidos, plural colectivo', 'Ungidos, plural colectivo. El plural colectivo que se refiere a un grupo protegido — patriarcas y profetas — a quienes Dios llama ''mis ungidos'' (Sal 105:15; 1 Cr 16:22). El plural con sufijo de primera persona (meshichai) extiende el concepto más allá de un solo portador del oficio a toda una clase de personas divinamente consagradas. Este sentido corporativo se confirma con el mandato paralelo ''no hagáis mal a mis profetas.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114649, 'spa', 'Ser prolongado o diferido (Nifal/Pual)', 'Ser prolongado o diferido (Nifal/Pual). Formas pasivas Nifal y Pual: ser prolongado, retrasado o diferido. Proverbios 13:12, ''La esperanza que se demora enferma el corazón,'' es el caso más conocido. Ezequiel asegura dos veces que las visiones proféticas no serán prolongadas indefinidamente (Ez 12:25, 28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114650, 'spa', 'Sacar o extraer físicamente', 'Sacar o extraer físicamente. Sacar, extraer o arrancar físicamente un objeto o persona — el sentido básico en Qal de ejercer fuerza. Abarca desde sacar a José del pozo (Gn 37:28) hasta tensar un arco en batalla (1 R 22:34). La raíz concreta de la que brotan todos los sentidos figurados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114651, 'spa', 'De estatura alargada', 'De estatura alargada. Aplicado a personas de estatura o apariencia inusual en Isaías 18:2 y 18:7, describiendo una nación ''alta y lampiña'' — literalmente ''estirada'' en complexión. Este sentido especializado extiende la metáfora de estiramiento para describir las proporciones corporales de una nación lejana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114653, 'spa', 'Atraer (personas)', 'Atraer (personas). Atraer a una persona relacional o emocionalmente, implicando influencia en lugar de fuerza física. Oseas 11:4, ''Con cuerdas de amor los atraje,'' y Jeremías 31:3, ''Con misericordia te atraje,'' ilustran la atracción tierna y persistente de Dios hacia su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114654, 'spa', 'Extender, prolongar', 'Extender, prolongar. Extender, estirar o prolongar en tiempo o espacio — la fuerza de tracción aplicada a la duración o dimensión. Se usa de Dios extendiendo su misericordia (Sal 36:10), prolongando su paciencia (Neh 9:30) y estirando su tolerancia (Sal 85:5). La metáfora raíz es tirar de algo para hacerlo más largo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114656, 'spa', 'Prolongar un sonido (de cuerno)', 'Prolongar un sonido (de cuerno). Prolongar un sonido musical, específicamente el toque sostenido del cuerno de carnero (שׁוֹפָר). En el Sinaí, el pueblo debía subir al monte ''cuando se prolongue el sonido del cuerno'' (Éx 19:13); en Jericó, los muros cayeron ante el sonido prolongado (Jos 6:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114661, 'spa', 'Empuñar, manejar (arma)', 'Empuñar, manejar (arma). Empuñar o manejar un arma, especialmente un arco, describiendo guerreros en batalla. Jueces 5:14 habla de quienes ''empuñan el bastón de escriba,'' e Isaías 66:19 menciona a quienes ''tensan el arco'' — guerreros diestros con las armas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114662, 'spa', 'Arrastrar con violencia', 'Arrastrar con violencia. Arrastrar o llevarse por la fuerza, con connotaciones de violencia o compulsión. Isaías 5:18 describe a quienes ''arrastran la iniquidad con cuerdas de vanidad,'' mientras que el Salmo 28:3 suplica ''no me arrastres con los impíos.'' La evidencia multilingüe distingue consistentemente esto de la atracción suave.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114666, 'spa', 'Alcanzar, empalmar (agricultura)', 'Alcanzar, empalmar (agricultura). Una única ocurrencia en Amós 9:13 donde el sembrador ''alcanza'' al segador, describiendo una abundancia agrícola tan grande que la siembra se empalma con la cosecha. El contexto de plenitud escatológica sugiere una superposición temporal-espacial — una estación ''alcanzando'' a la siguiente en profusión milagrosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114683, 'spa', 'Mesec (nombre propio, pueblo/región)', 'Nombre propio gentilicio que designa un pueblo y territorio de Asia Menor descendiente de Jafet. Los textos genealógicos (Gn 10:2; 1 Cr 1:5, 17) sitúan a Mesec entre los hijos de Jafet, junto a Tubal y Tirás. Los textos proféticos lo emparejan sistemáticamente con Tubal como potencia comercial y militar (Ez 27:13; 38:2-3; 39:1), mientras que el Salmo 120:5 usa el nombre como sinónimo de un exilio remoto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114686, 'spa', 'Cama, lecho', 'Cama o lecho donde uno se recuesta para dormir, lugar de visiones divinas nocturnas en las secciones arameas de Daniel. Cada aparición está vinculada a sueños reveladores: las visiones de Nabucodonosor en su cama (Dn 2:28-29; 4:5, 10, 13) y la visión nocturna de Daniel (Dn 7:1). Las glosas multilingües confirman un único sentido concreto con variación posesiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114689, 'spa', 'Cama, lecho (mueble)', 'Cama, lecho (mueble). La cama o lecho físico como mueble para dormir, descansar o reclinarse. Es el sentido dominante, cubriendo más de dos tercios de las ocurrencias. Incluye camas de enfermos (Éx 21:18), camas declaradas inmundas (Lv 15:4-5, 21), camas donde el salmista llora (Sal 6:7) y el lecho de los amantes en Cantares 3:1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114692, 'spa', 'Relaciones sexuales (acostarse con)', 'Relaciones sexuales (acostarse con). Eufemismo para relaciones sexuales, literalmente ''acostamientos de.'' Aparece exclusivamente en el plural constructo mishkeve, en el Código de Santidad (Lv 18:22; 20:13) y en el censo de las cautivas madianitas (Nm 31:17-18, 35). El plural intensifica o abstrae el acto, distanciándolo a un registro legal y ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114696, 'spa', 'Dormitorio, alcoba', 'Dormitorio, alcoba. El dormitorio o alcoba como habitación privada, usado metonímicamente de modo que la cama representa el espacio a su alrededor. Las ranas de la plaga invaden la ''alcoba'' de Faraón (Éx 8:3), Eliseo sabe lo que el rey de Aram habla ''en su dormitorio'' (2 R 6:12), y Eclesiastés advierte contra maldecir al rey incluso en la ''alcoba'' (Ec 10:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114702, 'spa', 'Acto de acostarse, descanso', 'Acto de acostarse, descanso. El acto abstracto de acostarse o descansar, donde el sustantivo denota la actividad en lugar del lugar o mueble. En 2 Samuel 4:5, 7, Is-boset es asesinado durante su ''siesta'' del mediodía, y Jueces 21:12 usa el término para la condición de no haber conocido varón. El sentido se centra en la postura y el estado de reposo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114723, 'spa', 'Maskil (titulo de salmo) -- Designacion de genero salmico en los titulos, deriva', 'Maskil (titulo de salmo) -- Designacion de genero salmico en los titulos, derivada del Hifil de שָׂכַל (''actuar con prudencia, dar entendimiento''), que probablemente indica un poema contemplativo, una composicion didactica o un canto artisticamente elaborado. Atestiguado en los titulos de los Salmos 32, 42, 44, 45, 52, 53, 54, 55, 74, 78, 88, 89 y 142, y como imperativo en el Salmo 47:7 (''cantad un maskil''). Los salmos maskil abarcan confesion (Sal 32), lamento (Sal 44, 74, 88), instruccion historica (Sal 78) y alabanza real (Sal 45).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114724, 'spa', 'Imagen tallada, piedra labrada', 'Imagen tallada o grabada, especialmente una piedra idolátrica condenada por la ley israelita. Levítico 26:1 prohíbe erigir una ''even maskit'' junto a pilares e ídolos; Números 33:52 ordena destruir las piedras labradas de los cananeos. Ezequiel 8:12 extiende el sentido a imágenes pintadas en muros de cámaras secretas de culto idolátrico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114727, 'spa', 'Imaginación, presunción', 'Imaginación, presunción o representación mental: la contraparte interior de la imagen externa tallada. En el Salmo 73:7 el salmista observa a los impíos cuyas ''imaginaciones del corazón'' desbordan sin límite. Proverbios 18:11 la emplea para la riqueza del rico como muro alto ''en su imaginación,'' una fortaleza ilusoria de la mente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114728, 'spa', 'Engaste ornamental', 'Engaste ornamental, marco decorativo u obra de fina artesanía. Proverbios 25:11 compara la palabra oportuna con ''manzanas de oro en engastes (maskiyyot) de plata,'' usando el término positivamente para el arte y no la idolatría. El español ''engastes'' capta el oficio del orfebre, mostrando cómo la misma raíz que denota imágenes prohibidas celebra también la belleza legítima.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114731, 'spa', 'Tabernáculo, santuario sagrado', 'El Tabernáculo: el santuario portátil de Israel y tienda de reunión, lugar designado de la presencia inmanente de Dios durante el período del desierto y más allá. Este sentido representa 109 de las 139 apariciones y domina la fuente sacerdotal de Éxodo a Números. Su traducción es altamente técnica y consistente: ''tabernáculo'' en todas las lenguas romances.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114735, 'spa', 'morada, habitación', 'Morada, habitación o residencia en sentido amplio, usado de la morada celestial o templar de Dios en contextos poéticos, o de habitaciones humanas y comunitarias. El oráculo de Balaam admira las ''moradas'' de Israel (Nm 24:5), el salmista celebra el מִשְׁכָּן de Dios entre su pueblo (Sal 46:5; 26:8), y Job describe las moradas de los malvados (Job 18:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114766, 'spa', 'Salario o recompensa', 'Salario o paga por servicio, empleado tanto en sentido comercial como teológico. En Génesis 29:15, Labán pregunta a Jacob por su salario por pastorear sus rebaños, estableciendo el contexto del acuerdo nupcial. Génesis 31:7 y 41 relatan la manipulación engañosa de Labán, cambiando el salario de Jacob diez veces durante catorce años. Rut 2:12 eleva el concepto: Boaz invoca la recompensa plena de YHWH por la fidelidad de Rut.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114767, 'spa', 'Qal', 'Qal: gobernar, administrar. Gobernación administrativa u oficial en el Qal: gobernar como administrador, supervisor o juez, no mediante la fuerza bruta. José gobernando sobre Egipto (Gn 45:26) o el gobernador designado sobre un distrito (Sal 105:20). Se distingue del mero dominio por su matiz burocrático e institucional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114768, 'spa', 'Qal', 'Qal: dominar, ejercer poder. El uso más amplio del Qal: ejercer dominio, señorío o control sobre personas, animales o cuerpos cósmicos. A menudo conlleva un matiz de sujeción o autoridad impuesta: el sol gobernando el día (Gn 1:18), el pecado acechando para dominar a Caín (Gn 4:7) o el marido ejerciendo autoridad sobre su mujer (Gn 3:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114775, 'spa', 'Qal', 'Qal: reinar soberanamente. Gobierno específicamente real o monárquico: reinar como soberano. Concentrado en las narraciones de Jueces (Jue 8:22-23; 9:2), donde Israel debate si Gedeón y sus hijos deben ''reinar'' sobre ellos. El árabe مَلَكَ (''ser rey'') y el alemán regieren (''reinar'') aparecen aquí en lugar del vocabulario de gobernación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114794, 'spa', 'Hifil', 'Hifil: hacer gobernar, dar dominio. El causativo Hifil: hacer que alguien gobierne, otorgar dominio, establecer como gobernante. Solo tres apariciones: Dios otorgando al ser humano dominio sobre la creación (Sal 8:6), Dios ejerciendo dominio soberano (Job 25:2) y un rey confiriendo autoridad (Dn 11:39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114826, 'spa', 'Ser semejante, comparar', 'Ser semejante, llegar a parecerse o ser comparado con otro, abarcando el Nifal (pasivo/reflexivo: ''ser asemejado''), el Hifil (causativo: ''comparar, asemejar'') y el Hitpael (reflexivo: ''hacerse semejante''). En el Salmo 49:12, 20 el Nifal נִמְשַׁל declara que aun el hombre honrado es semejante a las bestias. En Isaías 46:5 el Hifil lanza el reto de a quién se puede comparar a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114832, 'spa', 'Hablar en proverbios', 'Hablar en proverbios o parábolas, componer o recitar dichos proverbiales — verbo denominativo de mashal. En Números 21:27, los moshelim son compositores de baladas que conmemoran la conquista. Ezequiel domina el uso: Dios manda «propón una parábola» (Ez 17:2; 24:3), el pueblo cita el proverbio «los días se alargan» (12:23) y acusan a Ezequiel de hablar en enigmas (20:49).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114840, 'spa', 'Oráculo profético, discurso', 'Oráculo profético, discurso. Un oráculo o discurso visionario profético, especialmente los pronunciamientos de Balaam introducidos con la fórmula ''pronunció su parábola'' (Nm 23:7, 18; 24:3, 15, 20-23). El mashal oracular se distingue del proverbio sapiencial por su fuente divina y su alcance poético y visionario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114841, 'spa', 'Proverbio, dicho sapiencial', 'Proverbio, dicho sapiencial. Un dicho sapiencial breve y memorable, la materia de la tradición sapiencial israelita. Es el mashal de Proverbios 1:1 (mishle Shelomo), de los legendarios 3.000 proverbios de Salomón (1 R 4:32) y del ''proverbio de los antiguos'' citado por David (1 S 24:13). Eclesiastés 12:9 confirma la actividad del sabio de ordenar y componer proverbios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114844, 'spa', 'Parábola, discurso figurado', 'Parábola, discurso figurado. Una narrativa figurada extensa o alegoría usada para ilustrar una verdad espiritual. La alegoría del águila y la vid de Ezequiel (Ez 17:2) es llamada explícitamente mashal, al igual que el ''dicho oscuro'' del salmista en el Salmo 78:2. Isaías 14:4 la emplea para el gran poema de burla contra el rey de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114847, 'spa', 'Refrán, dicho de escarnio', 'Refrán, dicho de escarnio. Refrán u objeto de escarmiento — cuando una persona o nación se convierte en ejemplo proverbial de juicio y desgracia. Deuteronomio 28:37 advierte que Israel será ''proverbio y refrán'' entre las naciones, y el Salmo 44:14 lamenta esta suerte en el exilio. La misma raíz que construye sabiduría aquí construye vergüenza pública.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114867, 'spa', 'Empresa, emprendimiento', 'El acto de extender la mano o emprender algo, es decir, una empresa, emprendimiento u obra. Seis de las siete apariciones se encuentran en las fórmulas de bendición de Deuteronomio: Dios bendecirá ''toda obra de tu mano'' (Dt 12:7, 12:18, 15:10, 23:20, 28:8), mientras que Dt 28:20 usa la misma frase en sentido de maldición. Isaías 7:25 la aplica concretamente al ''soltar'' de ganado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114869, 'spa', 'Extensión y envío', 'Extensión o envío. Isaías 11:14 profetiza el dominio futuro de Israel: ''Edom y Moab serán la extensión de su mano'', territorio que poseerán. Ester 9:19, 22 describe las costumbres de Purim: ''días de banquete y alegría, y de enviar porciones de comida unos a otros'', el gozoso reparto de obsequios entre los judíos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114871, 'spa', 'Nombre propio hebreo que significa ''retribuido'' o ''consagrado'', derivado de la r', 'Nombre propio hebreo que significa ''retribuido'' o ''consagrado'', derivado de la raíz shalem. Se aplica a al menos nueve personas distintas: el abuelo del escriba Safán (2 R 22:3), un hijo de Zorobabel (1 Cr 3:19), un jefe gadita (1 Cr 5:13), cabezas de clanes benjaminitas (1 Cr 8:17; 9:7-8), sacerdotes y levitas involucrados en la restauración del templo (1 Cr 9:11-12; 2 Cr 34:12; Esd 8:16; 10:15) y constructores del muro de Jerusalén bajo Nehemías (Neh 3:4, 6, 30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114875, 'spa', 'Portero levita coraíta', 'Nombre personal levítico, específicamente un portero coraíta. 1 Crónicas 9:21 identifica a «Meselemías hijo de Coré» como portero de la entrada de la tienda de reunión, cargo establecido desde época temprana. 1 Crónicas 26:1-2, 9 ofrece más detalles: tenía siete hijos que también servían como porteros y formaba parte de la organización de David para el servicio del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114878, 'spa', 'Devastación, desolación', 'Devastación, desolación o ruina: la condición arrasada de tierras o lugares tras un juicio catastrófico, y por extensión el horror o espanto que tal ruina provoca. En Ezequiel 6:14 y 33:28-29 Dios declara que hará la tierra ''desolación y devastación'' (שְׁמָמָה וּמְשַׁמָּה), intensificando la imagen de destrucción total. En Ezequiel 5:15 el término se desliza hacia la reacción emocional de horror entre las naciones testigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114884, 'spa', 'Gordura o robustez', 'Gordura, ya sea como cualidad abstracta o como referencia concreta a personas corpulentas o regiones fértiles. Salmo 78:31 lo usa para «los más robustos de entre ellos» (מִשְׁמַנֵּיהֶם), los israelitas más fuertes abatidos en el desierto pese a estar bien alimentados. Isaías 10:16 profetiza que Dios enviará enfermedad consumidora «entre sus guerreros robustos» (מִשְׁמַנָּיו), contrastando su vigor aparente con la emaciación venidera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114888, 'spa', 'Nombre propio genealógico', 'Nombre personal portado por dos individuos en las genealogías de Israel: (1) Un hijo de Ismael, incluido entre los doce jefes tribales ismaelitas en Génesis 25:14 y la genealogía paralela en 1 Crónicas 1:30, representando un nombre tribal árabe entre los descendientes de Abraham por medio de Agar. (2) Un descendiente de la tribu de Simeón en 1 Crónicas 4:25-26.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114889, 'spa', 'Guardia o escolta leal', 'Cuerpo obediente o guardia personal, con énfasis en el servicio leal. 1 Samuel 22:14 defiende a Jonatán como «capitán de tu guardia» (מִשְׁמַעְתְּךָ), indicando una unidad selecta cercana al rey. 2 Samuel 23:23 y su paralelo en 1 Crónicas 11:25 describen a un guerrero honrado «sobre su guardia» (מִשְׁמַעְתּוֹ), un cargo de confianza en la organización militar de David. Isaías 11:14 lo emplea metafóricamente en profecía respecto a la sumisión futura de pueblos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114890, 'spa', 'El acto de montar guardia o hacer vigilia, o el grupo de guardias que desempeña ', 'El acto de montar guardia o hacer vigilia, o el grupo de guardias que desempeña esa función. Nehemías 4:9 y 4:22-23 describen la vigilancia permanente mantenida durante la reconstrucción de Jerusalén. Jeremías 51:12 exhorta a reforzar la guardia contra Babilonia. El término designa la protección activa y organizada de una posición o comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114891, 'spa', 'Lugar de reclusión, custodia o encarcelamiento', 'Lugar de reclusión, custodia o encarcelamiento. En Génesis 40:3-7 y 41:10 se refiere a la casa del capitán de la guardia donde José interpreta sueños, y en Génesis 42:17 José pone a sus hermanos bajo custodia durante tres días. Levítico 24:12 y Números 15:34 lo usan para la detención temporal en el campamento en espera de un veredicto divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114896, 'spa', 'Puesto de guardia asignado, estación de vigilancia u obligación de servicio pres', 'Puesto de guardia asignado, estación de vigilancia u obligación de servicio prescrita. Nehemías 7:3 asigna a cada persona montar guardia en su puesto, y Nehemías 13:14 registra los deberes levíticos para el templo. Ezequiel 38:7 lo emplea con sentido de disponibilidad militar como fuerza de reserva. Este sentido enfatiza la asignación institucional más que el acto de vigilar o el lugar de confinamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114902, 'spa', 'Encargo, deber asignado', 'Encargo, deber asignado. Encargo asignado, deber sagrado: el sentido dominante con 54 apariciones, abrumadoramente en la legislación levítica de Números y Crónicas. Los levitas reciben el encargo del tabernáculo (Nm 1:53; 3:7-8, 25, 28, 31, 32, 36, 38), cubriendo desde las cortinas y armazones hasta los utensilios del altar. Cada clan recibe su cargo específico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114903, 'spa', 'Custodia, resguardo', 'Custodia, resguardo. Custodia, resguardo, almacenamiento protector: 9 apariciones donde algo valioso se pone bajo vigilancia. El cordero pascual se guarda en custodia hasta el día catorce (Éx 12:6); la vasija de maná se deposita en resguardo ante el testimonio (Éx 16:23, 32-34); las concubinas de David son puestas en casa de custodia (2 Sam 20:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114911, 'spa', 'Mandamiento, ordenanza', 'Mandamiento, ordenanza. Mandamiento, ordenanza divina: 6 apariciones donde mishmeret se refiere a los requisitos morales o pactuales más amplios de Dios, no específicamente al servicio levítico. El pasaje fundamental es Gn 26:5: Abraham guardó la mishmeret, las mitzvot, los juqqot y las torot de Dios. Lv 18:30 y 22:9 usan el término para el encargo divino de mantener la santidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114912, 'spa', 'Puesto de guardia', 'Puesto de guardia. Puesto de guardia, estación de vigía: 3 apariciones donde mishmeret designa el lugar físico de vigilancia. Isaías 21:8 sitúa al centinela en su mishmeret (paralelo a מִצְפֶּה, ''atalaya''); Habacuc 2:1 declara: ''Me apostaré en mi mishmeret y me situaré sobre la muralla.'' En 1 Cr 9:27 los porteros se alojan alrededor del templo porque la mishmeret les pertenece.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114917, 'spa', 'Turno, guardia rotativa', 'Turno, guardia rotativa. Turno, guardia, rotación de servicio: 5 apariciones que describen la organización temporal del servicio. Los porteros levíticos sirven por rotaciones de mishmeret (1 Cr 9:23; 25:8; 26:12), y Nehemías organiza al personal del templo post-exílico en divisiones de mishmeret (Neh 12:9; 13:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114924, 'spa', 'Guardias (personas)', 'Guardias (personas). Guardias (personas que sirven como vigías): 1 aparición en Neh 7:3, donde Nehemías establece mishmeret (''guardias'') en las puertas de Jerusalén de entre los habitantes de la ciudad. Representa una extensión metonímica del deber abstracto (sentido 1) o del puesto físico (sentido 5) a las personas concretas que realizan la guardia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114936, 'spa', 'Doble, cantidad duplicada', 'Doble, cantidad duplicada. Indica una cantidad doble o duplicada — ''doble de dinero'' en Génesis 43:12, 15, ''doble de pan'' para la porción de maná del sexto día (Éx 16:5, 22), o ''el doble de su iniquidad'' en Jeremías 16:18. Se distingue claramente del sentido ordinal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114937, 'spa', 'Segundo (rango u orden)', 'Segundo (rango u orden). Denota la segunda posición en rango u orden — usado sustantivamente para el segundo al mando (Gn 41:43), el hijo segundogénito (1 S 8:2; 2 S 3:3) o cosas en segundo lugar. Las traducciones multilingües confirman consistentemente la lectura ordinal en las 18 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114939, 'spa', 'Copia (de un documento)', 'Copia (de un documento). Copia o duplicado escrito de un documento, especialmente en Deuteronomio 17:18 donde el rey debe escribir ''una copia de esta Torá'' (mishneh hattorah), y Josué 8:32 donde Josué inscribe una copia de la ley de Moisés sobre piedras. Este sentido subyace al título rabínico posterior ''Mishná'' para la ley oral codificada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114945, 'spa', 'Segundo Barrio (distrito de Jerusalén)', 'Segundo Barrio (distrito de Jerusalén). Topónimo propio para el Segundo Barrio (ha-Mishneh) de Jerusalén, un distrito residencial en la parte occidental más nueva de la ciudad. La profetisa Hulda ''habitaba en el Segundo Barrio'' (2 R 22:14; 2 Cr 34:22), y Sofonías 1:10 predice un clamor desde este distrito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114949, 'spa', 'Reses cebadas, animales selectos', 'Reses cebadas, animales selectos. Un uso poco frecuente en 1 Samuel 15:9 que aparentemente denota ''reses cebadas'' o ganado selecto — posiblemente derivado del sentido de animales engordados de ''segunda calidad'' o animales de la mejor clase entre el botín. La tradición interpretativa se halla atestiguada en el Targum.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114958, 'spa', 'Saqueo, despojo, botín', 'Saqueo, despojo o botín: bienes y posesiones arrebatados violentamente en conquistas o incursiones, particularmente como consecuencia de juicio divino contra un pueblo. Aparece habitualmente en la fórmula hayah li-meshissah (''convertirse en saqueo''), frecuentemente emparejado con בַּז (''botín'') para mayor énfasis. En 2 Reyes 21:14, Dios anuncia la entrega total de Israel a sus adversarios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114967, 'spa', 'Apoyo o sustento', 'Apoyo, bastón o provisión sustentadora. En 2 Samuel 22:19 y su paralelo Salmo 18:18 se declara ''YHWH fue mi apoyo'' (מִשְׁעָנִי), usando la imagen de un bastón para describir la ayuda sustentadora de Dios en la angustia. Isaías 3:1 contiene un juego de palabras: Dios retirará ''todo apoyo de pan y todo apoyo de agua'', subrayando que las provisiones básicas son el sostén de la vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114970, 'spa', 'Bastón, cayado', 'Un bastón literal o vara de apoyo usada para auxilio físico, especialmente por ancianos, heridos o viajeros. Un hombre herido camina con su bastón durante la recuperación (Éx 21:19), los ancianos se sientan con bastones en la Jerusalén restaurada (Zac 8:4), Gedeón es tocado por el bastón del ángel (Jue 6:21) y Eliseo envía su bastón como instrumento vicario de poder (2 R 4:29-31). El cayado del pastor en Salmo 23:4 consuela al creyente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114980, 'spa', 'clan, grupo familiar', 'Clan o grupo familiar extenso dentro de una tribu israelita: la subdivisión primaria de parentesco usada para censos, reparto de tierras, organización militar y participación ritual (303 apariciones). Dominante en Números 3 y 26, donde se enumeran los clanes levíticos y tribales, y en Josué 7, donde la identificación de Acán procede de tribu a מִשְׁפָּחָה.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115037, 'spa', 'clase, categoría', 'Aparición única en Jeremías 15:3, donde el término designa ''cuatro clases de destructores'' — espada, perros, aves y bestias —, usando מִשְׁפָּחָה metafóricamente para categorías o tipos de agentes en lugar de grupos de parentesco humano. El español traduce ''clases'' en vez de ''familias'', reconociendo esta extensión figurada del vocablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115043, 'spa', 'justicia, rectitud', 'La cualidad moral abstracta de justicia y gobierno recto. Cuando Abraham pregunta ''¿No ha de hacer justicia el Juez de toda la tierra?'' (Gn 18:25), o cuando se alaba a Salomón por administrar justicia y rectitud (2 S 8:15), este sentido está en juego: la justicia como principio rector detrás de toda autoridad legítima.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115044, 'spa', 'juicio, veredicto judicial', 'Acto concreto de juzgar o veredicto judicial, ya sea humano o divino. Éxodo 28:15 llama al pectoral del sumo sacerdote ''pectoral del juicio'', vinculando este sentido a la toma de decisiones teofánica. La dimensión escatológica — el juicio venidero de Dios — se extiende naturalmente de aquí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115049, 'spa', 'ordenanzas, estatutos (plural)', 'La forma plural que designa las ordenanzas reunidas de Dios y las estipulaciones del pacto. Frecuentemente emparejado con ''estatutos'' (חֻקּוֹת) en la literatura levítica y deuteronómica (Lv 18:4; 26:46), estos son los preceptos casuísticos que concretan los principios de la Torá en normas comunitarias vinculantes para Israel con su Señor del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115057, 'spa', 'ordenanza, regulación prescrita', 'Una regulación o norma procedimental individual que rige la vida ritual o cívica. Donde el sentido 3 es colectivo, este es la ordenanza particular — ''conforme a la ordenanza'' (Éx 21:9, 31). Estos decretos establecen el procedimiento estándar para todo, desde el sacrificio (Lv 5:10) hasta el patrón de construcción del tabernáculo (Éx 26:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115067, 'spa', 'derecho, prerrogativa legítima', 'Derecho legítimo, prerrogativa o reclamación legal que corresponde a una persona por costumbre o ley. En Dt 18:3 es la porción que corresponde al sacerdote de los sacrificios; en Dt 21:17 es el derecho del primogénito a la doble porción hereditaria. Jr 32:7-8 lo usa del derecho de redención de Jeremías sobre un campo familiar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115073, 'spa', 'costumbre, modo, manera', 'Costumbre establecida, manera habitual o modo característico de hacer las cosas. Esta extensión semántica trasciende el ámbito judicial hacia la vida cotidiana. En Gn 40:13 el copero del faraón es restaurado para servir ''conforme a la costumbre anterior'', y 1 S 2:13 describe la costumbre de los sacerdotes en Siló.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115110, 'spa', 'causa legal, pleito', 'Disputa legal específica, causa o pleito presentado ante un juez para ser dirimido. Números 27:5 registra a las hijas de Zelofejad presentando su ''causa'' ante Moisés, mientras que Sal 35:23 e Is 50:8 invocan a Dios como quien defenderá la causa legal del salmista o del siervo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115191, 'spa', 'copero, mayordomo', 'Funcionario de la corte real cuya labor era servir vino al rey, actuando también como asistente personal de confianza con acceso íntimo al monarca. El cargo implicaba tanto honor como riesgo, pues el copero protegía al rey del envenenamiento. En Génesis 40, el copero mayor del faraón es encarcelado junto a José; su restauración al cargo se convierte en catalizador del ascenso de José al poder.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115199, 'spa', 'Bebida, líquido', 'Bebida, líquido o contenido de vasijas para beber. Se usa para las copas de oro de Salomón (1 R 10:21 = 2 Cr 9:20), para el líquido que puede transmitir impureza ritual a los alimentos (Lv 11:34) y para la bebida que el necio niega al sediento (Is 32:6). El español ''bebida'' traduce directamente este sentido de líquido consumible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115201, 'spa', 'Tierra bien regada', 'Tierra bien regada o irrigación: uso abstracto-por-concreto que designa tierra que ha recibido agua en abundancia. En Gn 13:10 la llanura del Jordán se describe como mashqeh, ''bien regada,'' como el jardín del SEÑOR. Ezequiel 45:15 extiende el sentido a pastos de tierras bien regadas. El español ''regada'' y el inglés ''well-watered'' destacan el ángulo de fertilidad agrícola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115206, 'spa', 'Dintel de puerta', 'El dintel, la viga horizontal que corona el marco de una puerta. Éxodo 12:7 ordena: ''tomarán de la sangre y la pondrán en los dos postes y en el dintel de las casas''. El versículo 22 instruye: ''tocad el dintel y los dos postes con la sangre que está en la vasija''. El versículo 23 promete: ''cuando el SEÑOR vea la sangre en el dintel y en los dos postes, pasará de largo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115207, 'spa', 'Peso, pesantez', 'Peso, pesantez. La pesantez medible de un objeto físico, típicamente expresada en siclos o talentos de oro, plata o bronce. Usado en inventarios de adornos personales (Gn 24:22), botín de guerra (Jue 8:26), armadura militar (1 Sam 17:5; 2 Sam 21:16), mobiliario del templo (1 Re 7:47) y ofrendas del tabernáculo (Nm 7:13-85). También tiene fuerza ética en las leyes que exigen honradez al pesar (Lv 19:35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115222, 'spa', 'Flauta o caramillo', 'Flauta o instrumento de viento de la orquesta real de Nabucodonosor. El término aparece cuatro veces en Daniel 3 (versículos 5, 7, 10, 15), siempre dentro de la lista formulaica de instrumentos que acompañaban la orden de adorar la estatua de oro: cuerno, flauta, cítara, arpa, salterio, gaita y toda clase de música. Las formas arameas muestran tanto la forma enfática como variantes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115228, 'spa', 'Tantear, buscar a tientas', 'Tantear o buscar a tientas (Piel intensivo), describiendo una búsqueda a ciegas y desesperada. Labán registró toda la tienda de Raquel palpando con las manos (Gn 31:34, 37). Como maldición del pacto, Israel andaría a tientas al mediodía como los ciegos (Dt 28:29). Job extiende esta imagen a los malvados que «tantean en la oscuridad» (Job 5:14, 12:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115229, 'spa', 'Palpar, tocar físicamente', 'Palpar o tocar físicamente con las manos (Qal, conjugación básica), contacto táctil directo. Aparece únicamente en el relato del engaño de Jacob a Isaac: Isaac teme que la piel suave de Jacob lo delate (Gn 27:12) y luego extiende la mano y lo palpa (Gn 27:22). No es un tanteo a ciegas, sino un examen cuidadoso y deliberado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115231, 'spa', 'Hacer palpar, dejar tocar', 'Hacer o permitir que alguien palpe o toque (Hifil causativo). La petición de Sansón —«hazme palpar las columnas»— emplea esta conjugación dos veces (Jue 16:26), al igual que la plaga de tinieblas que podían «hacerse sentir» (Éx 10:21). La fuerza causativa distingue este sentido del toque voluntario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115238, 'spa', 'Banquete, festín', 'Banquete, festín. Un festín o banquete — una ocasión social festiva que involucra comida y especialmente bebida. La colocación עָשָׂה מִשְׁתֶּה (''hacer un banquete'') es la fórmula bíblica estándar para celebrar un festín (Gn 19:3; 21:8; 26:30). El libro de Ester por sí solo representa aproximadamente un tercio de las ocurrencias, con sus elaborados banquetes reales y las fiestas de Purim.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115241, 'spa', 'Bebida, el acto de beber', 'Bebida, el acto de beber. La bebida misma o el acto de beber, enfocándose en el líquido en lugar de la ocasión social. En Daniel 1:5, 8, 10, 16 el término se refiere específicamente a las provisiones de bebida del rey — la ración de vino de la mesa de Nabucodonosor — que Daniel y sus compañeros rehusaron. El emparejamiento con las raciones de comida (פַּת־בַּג) en Daniel confirma el sentido concreto y no festivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115253, 'spa', 'Varones o hombres adultos colectivamente, designando a menudo un grupo perteneci', 'Varones o hombres adultos colectivamente, designando a menudo un grupo perteneciente a un lugar, líder o comunidad. Deuteronomio 2:34 y 3:6 usan la expresión ''ciudad de varones'' para identificar la población masculina distinta de mujeres y niños. En 1 Crónicas 16:19 y Job 11:3 el término funciona como designación general de personas o gente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115256, 'spa', 'Pocos en número, uso idiomático que aparece en la expresión constructa mete misp', 'Pocos en número, uso idiomático que aparece en la expresión constructa mete mispar (''hombres de número''), es decir, un grupo tan pequeño que se puede contar individualmente. Génesis 34:30 registra el temor de Jacob de ser ''pocos en número'' entre los cananeos. Deuteronomio 4:27, 26:5 y 28:62 advierten o recuerdan la escasez de Israel. El Salmo 105:12 celebra cómo Dios los eligió ''cuando eran pocos en número''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115262, 'spa', 'Mortales o moribundos, extensión poética que resalta la fragilidad humana y la t', 'Mortales o moribundos, extensión poética que resalta la fragilidad humana y la transitoriedad de la vida. Job 24:12 describe los gemidos de los moribundos (metim) que ascienden desde la ciudad. Esta única atestiguación aprovecha la profunda conexión semítica del vocablo con la mortalidad (cf. asirio mutu), confiriéndole un matiz más sombrío que el neutral ''hombres'' del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115268, 'spa', 'Freno o brida', 'Freno o brida para controlar animales. Proverbios 26:3 enumera instrumentos de disciplina: ''el látigo para el caballo, la brida para el asno y la vara para la espalda del necio'', herramientas paralelas para dominar criaturas irracionales. Salmo 32:9 advierte contra ser ''como el caballo o el mulo sin entendimiento, que necesitan freno y brida'', requiriendo fuerza externa en lugar de obediencia voluntaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115270, 'spa', 'Dulce, dulzura', 'Dulce al gusto o metafóricamente agradable. En sentido literal se aplica a la miel: la adivinanza de Sansón (Jue 14:14, 18) y los juicios de Dios, más dulces que el panal (Sal 19:10). En sentido figurado, de las palabras amables (Pr 16:24), el sueño del trabajador (Ecl 5:12) y el rollo profético dulce en la boca (Ez 3:3). Isaías advierte contra invertir lo dulce y lo amargo (Is 5:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115278, 'spa', 'Matusalén (nombre propio)', 'Nombre propio que designa al hijo de Enoc y abuelo de Noé en la genealogía setita. Su extraordinaria longevidad de 969 años (Gn 5:27) ha convertido su nombre en sinónimo universal de vejez extrema. La etimología se debate entre ''hombre del dardo'' y un posible préstamo babilónico. La Septuaginta lo transcribe como Μαθουσαλα, y el español lo adapta como Matusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115281, 'spa', 'Interrogativo ''cuando?'' referido al tiempo futuro', 'Interrogativo ''cuando?'' referido al tiempo futuro. Solo, plantea una pregunta directa (Gn 30:30; Neh 2:6); con le- significa ''para cuando?'' (Ex 8:5). En la construccion compuesta ''ad-matay se convierte en el grito de lamento ''hasta cuando?'' (Sal 74:10; 94:3). El frances ''quand'' y el espanol ''cuando'' reflejan la forma simple, mientras que ''hasta cuando'' capta la construccion ''ad-matay.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115284, 'spa', 'medida o proporcion fija', 'Una medida fija, cuota o proporcion aplicada a bienes, recetas sagradas o normas arquitectonicas. Exodo 5:8 la emplea para la cuota obligatoria de ladrillos bajo la esclavitud egipcia. Exodo 30:32, 37 estipulan la composicion exacta del aceite santo de la uncion. En 2 Cronicas 24:13 designa la especificacion original del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115286, 'spa', 'Colmillos o muelas', 'Colmillos, dientes o muelas, con énfasis en su cualidad devoradora y peligrosa. Job 29:17 declara: ''Quebraba los colmillos del injusto y le hacía soltar la presa de sus dientes'', rescatando víctimas de los opresores. Proverbios 30:14 advierte sobre aquellos ''cuyos dientes son espadas, cuyos colmillos son cuchillos, para devorar a los pobres''. Joel 1:6 describe la invasión de langostas con ''colmillos de león''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115287, 'spa', 'Sanidad o integridad', 'Sanidad, integridad o plenitud, generalmente en contextos negativos. Isaías 1:6 describe la condición espiritual de Israel en términos físicos: ''Desde la planta del pie hasta la cabeza no hay en él cosa sana (אֵין מְתֹם)'', solo heridas y contusiones. Salmo 38:3 y 7 emplean un lenguaje idéntico para describir la aflicción del salmista bajo el juicio divino: ''no hay sanidad en mi carne'' a causa de la ira de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115288, 'spa', 'La region anatomica de la espalda baja, cintura o caderas, referida como el luga', 'La region anatomica de la espalda baja, cintura o caderas, referida como el lugar donde se cinen las vestiduras, se sujetan las armas y se siente dolor o temblor. Con 43 de 47 apariciones, este es el sentido principal, abarcando desde el mandato del Exodo de comer con los ''lomos cenidos'' (Ex 12:11), las vestiduras sacerdotales de lino que cubren de la cintura al muslo (Ex 28:42), la espada de Joab cayendo de sus lomos (2 S 20:8), y el cinturon mesianico de justicia de Isaias (Is 11:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115301, 'spa', 'Los lomos entendidos metaforicamente como fuente de descendencia y origen biolog', 'Los lomos entendidos metaforicamente como fuente de descendencia y origen biologico, expresando el linaje mediante la expresion ''de los lomos de.'' Con cuatro apariciones, este sentido procreativo se encuentra en la jactancia de Roboam de que su dedo menique es mas grueso que los lomos de su padre (1 R 12:10; 2 Cr 10:10) -- donde ''lomos'' representa el poder generativo del padre -- y en la vision de Ezequiel (Ez 8:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115319, 'spa', 'regalo o dadiva', 'Un regalo o presente entregado en contextos sociales, matrimoniales o sagrados, con el matiz de algo ofrecido para obtener favor o cumplir una obligacion. Genesis 34:12 lo empareja con el precio de la novia. Numeros 18:11 designa ofrendas sacerdotales. Proverbios 18:16 y 21:14 describen como una dadiva abre puertas y aplaca la ira.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115320, 'spa', 'Nombre propio personal', 'Matán, nombre propio que significa ''don''. El sacerdote de Baal llamado Matán servía en Jerusalén y fue ejecutado durante la restauración de Joás: ''todo el pueblo de la tierra fue al templo de Baal y lo derribaron; mataron a Matán, sacerdote de Baal, delante de los altares'' (2 Re 11:18; cf. 2 Cr 23:17). Un segundo Matán aparece en Jeremías 38:1 como padre de Sefatías, uno de los príncipes que se opusieron a Jeremías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115321, 'spa', 'Dones regios', 'Dones o recompensas de parte de un rey. Daniel 2:6 promete: «recibiréis de mí dones, recompensas y gran honra.» El versículo 48 narra su cumplimiento: «el rey colmó a Daniel de dones y grandes recompensas.» En 5:17, Daniel responde a Belsasar: «Quédense tus dones para ti y da tus recompensas a otro», rechazando el pago antes de interpretar la escritura en la pared.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115322, 'spa', 'Don u ofrenda', 'Don u ofrenda: regalo voluntario, presente u ofrenda sagrada entregada libremente, ya sea a Dios o a otra persona. Los regalos de Abraham a sus hijos (Gn 25:6), las ofrendas santas que Israel presenta ante el SEÑOR (Éx 28:38), y las ofrendas voluntarias levíticas distintas de votos y promesas (Lv 23:38) entran aquí. Números 18 define la porción sacerdotal de estos dones. La frase clave ''según el don de su mano'' (Dt 16:17) vincula la generosidad con la capacidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115329, 'spa', 'Soborno o don corruptor', 'Soborno o don corruptor: regalo destinado a influir o corromper; un soborno. Proverbios 15:27 advierte que ''el que aborrece los sobornos (מַתָּנֹת) vivirá,'' y Eclesiastés 7:7 lamenta que ''el don destruye el corazón.'' El mismo sustantivo que describe la generosidad sagrada en el sentido 1 aquí nombra la perversión del dar, donde la intención pasa de la adoración o el amor a la manipulación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115336, 'spa', 'Nombre propio', 'Matenai, nombre personal (forma abreviada de Matanías). Esdras 10:33 lo enumera entre los descendientes de Hasum que «habían tomado mujeres extranjeras», parte de la crisis de matrimonios mixtos. Esdras 10:37 menciona otro Matenai entre los descendientes de Baní en la misma situación. Nehemías 12:19 identifica a un Matenai sacerdote: «de Joiarib, Matenai», sacerdote de la generación posterior al retorno del exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115337, 'spa', 'Matanías (nombre propio)', 'Matanías (nombre propio): nombre masculino propio que designa a múltiples individuos bíblicos cuyo nombre significa ''don de YHWH.'' El nombre se concentra abrumadoramente entre cantores levíticos y personal del templo —asafitas y hemanitas que servían en el culto (1 Cr 25:4, 16; Neh 11:17; 12:8, 35). Una excepción notable es el rey títere instalado por Nabucodonosor y renombrado Sedequías (2 R 24:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115342, 'spa', 'endulzarse o ser dulce', 'Volverse o ser dulce, agradable, ya sea literalmente del sabor del agua o figuradamente de experiencias y placeres. Exodo 15:25 registra las aguas de Mara endulzandose, el unico uso narrativo. Proverbios 9:17 advierte sobre la dulzura enganosa de las aguas robadas. Job 21:33 y 20:12 extienden la imagen al deleite del malvado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115348, 'spa', 'Don, regalo, dádiva', 'Un don o regalo otorgado de una parte a otra, abarcando dones divinos, recompensas humanas y ofrendas voluntarias. La expresión ''don de su mano'' (Ez 46:5, 11) expresa dar según la capacidad, mientras que ''don de Dios'' (Ec 3:13; 5:19) presenta los goces como bendiciones divinas. Proverbios 25:14 añade un giro irónico: un regalo prometido pero jamás entregado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115352, 'spa', 'Matatías (nombre propio)', 'Nombre personal teofórico Matatías/Matityahu, que significa ''don de YHWH'', portado por varios personajes en textos postexílicos y del período monárquico tardío. El portador más destacado es el músico levita en las disposiciones cultuales de David (1 Cr 15:18, 21; 16:5; 25:3, 21). Otros portadores incluyen un levita panadero (1 Cr 9:31), un asistente en la lectura de la Torá bajo Esdras (Neh 8:4) y un hombre en la lista de matrimonios mixtos (Esd 10:43).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115357, 'spa', 'por favor, te ruego', 'Partícula discursiva enclítica que se adhiere principalmente a imperativos y cohortativos para expresar súplica, petición cortés o atenuación retórica. Su tono abarca desde la cortesía amable (Gn 13:9, ''sepárate, por favor'') hasta la urgencia extrema (Gn 22:2) y el desafío irónico (Is 47:12). Prácticamente intraducible como palabra aislada, modula la fuerza ilocutiva del verbo que acompaña.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115364, 'spa', 'Ciudad egipcia de Tebas', 'Nombre propio para Tebas, la gran ciudad del Alto Egipto y centro de culto del dios Amón. Las cinco apariciones se hallan en oráculos proféticos de juicio contra Egipto. Nahúm 3:8 emplea la forma No-Amón para comparar la ruina de Nínive con la caída de Tebas. Ezequiel 30:14-16 la enumera junto a otras fortalezas egipcias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (115365, 'spa', 'Odre, pellejo', 'Recipiente de cuero para transportar vino, leche u otros líquidos, objeto cotidiano en el antiguo Cercano Oriente. Literalmente designa provisiones de viaje (Jos 9:4, 13) y recipientes de hospitalidad (Jue 4:19; 1 S 16:20). Figuradamente, Dios guarda lágrimas en un odre (Sal 56:8) y el salmista se siente como odre arrugado al humo (Sal 119:83).');